RSpec.describe Timekeeping::ReconciliationDifferenceFound do
  let(:reconciliation_event_difference) do
    Data.define(:company_id, :check, :table, :row_key, :field, :reason, :note, :duration)
  end

  it "names the difference by identifiers only" do
    difference = reconciliation_event_difference.new(
      company_id: 101, check: :entries, table: "entries", row_key: [7], field: "note", reason: :changed,
      note: "private-memo-text", duration: 61.25
    )

    data = described_class.new(difference, listed: false, actor: nil).to_h[:data]

    expect(data).to eq(
      company_id: 101, check: :entries, table: "entries", row_key: [7], field: "note", reason: :changed, listed: false
    )
    expect(JSON.generate(data)).not_to include("private-memo-text")
    expect(JSON.generate(data)).not_to include("61.25")
  end

  it "marks a difference the pre-flight listed" do
    difference = reconciliation_event_difference.new(
      company_id: 202, check: :projection, table: "entries", row_key: [7], field: "locked", reason: :changed,
      note: nil, duration: nil
    )

    data = described_class.new(difference, listed: true, actor: nil).to_h[:data]

    expect(data[:listed]).to be(true)
    expect(data[:company_id]).to eq(202)
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation, "check by check" do
  let(:recon_checks_time) { Time.utc(2026, 1, 5, 9) }
  let(:recon_checks_operation_id) { "11111111-1111-1111-1111-111111111111" }

  def recon_checks_entry(company_id, **overrides)
    # locked is true because recon_checks_tables gives every entry a committed
    # reservation; an unreserved entry must override locked to false as well.
    {
      "id" => 1, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1,
      "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => recon_checks_time, "updated_at" => recon_checks_time
    }
      .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("entries").index_with { nil })
      .merge(overrides.transform_keys(&:to_s))
  end

  # The projection stores bill_status and review_status as integer enums,
  # where the checkpoint keeps their names.
  def recon_checks_projection(entry_rows)
    entry_rows.map do |row|
      row.merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
        "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"])
      )
    end
  end

  def recon_checks_snapshot(company_id, values = {})
    { company_id:, values: }
  end

  def recon_checks_snapshots
    [101, 202].index_with { |company_id| recon_checks_snapshot(company_id) }
  end

  def recon_checks_reservation(company_id, **overrides)
    { "company_id" => company_id, "entry_id" => 1, "invoice_id" => 1, "state" => "committed",
      "disposition" => "active", "operation_id" => recon_checks_operation_id,
      "created_at" => recon_checks_time }
      .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
      .merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_operation(company_id, **overrides)
    { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => recon_checks_operation_id,
      "state" => "committed", "desired_entry_ids" => [1], "disposition" => "active", "generation" => 1,
      "created_at" => recon_checks_time, "finished_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_intent(company_id, **overrides)
    { "company_id" => company_id, "invoice_id" => 1, "operation_id" => recon_checks_operation_id, "generation" => 1,
      "desired_entry_ids" => [1], "disposition" => "active", "state" => "committed", "created_at" => recon_checks_time,
      "finished_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_audit(company_id, **overrides)
    { "id" => 1, "company_id" => company_id, "entry_id" => 1, "actor_type" => "User", "actor_id" => 1,
      "action" => "create", "before" => nil, "after" => { "note" => "" },
      "entry_created_at" => recon_checks_time, "created_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_receipt(company_id, **overrides)
    { "id" => 1, "company_id" => company_id, "actor_type" => "User", "actor_id" => 1, "operation" => "create_entry",
      "key" => "key-1", "fingerprint" => "abc", "status" => 201, "body" => { "id" => 1 },
      "created_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  # Both companies hold the same ids, so a check keyed by row id alone would mix them.
  def recon_checks_tables(**changes_for_a)
    tables = {
      "entries" => [recon_checks_entry(101), recon_checks_entry(202)],
      "reservations" => [recon_checks_reservation(101), recon_checks_reservation(202)],
      "invoice_operations" => [recon_checks_operation(101), recon_checks_operation(202)],
      "entry_audits" => [recon_checks_audit(101), recon_checks_audit(202)],
      "idempotency_records" => [recon_checks_receipt(101), recon_checks_receipt(202)]
    }
    changes_for_a.each do |table, rows_for_a|
      tables[table.to_s] = rows_for_a + tables[table.to_s].reject { |row| row["company_id"] == 101 }
    end
    recon_checks_canonical(tables)
  end

  # Fills every canonical checkpoint column a fixture row leaves out with nil,
  # so the rows keep fitting Checkpoint::TABLES when it gains a column.
  def recon_checks_canonical(tables)
    tables.to_h do |table, rows|
      defaults = Timekeeping::Handoff::Checkpoint::TABLES.fetch(table).index_with { nil }
      [table, rows.map { |row| row.reverse_merge(defaults) }]
    end
  end

  def recon_checks_run(checkpoint_tables: recon_checks_tables, projection: nil, source_tables: recon_checks_tables,
                       intents: [recon_checks_intent(101), recon_checks_intent(202)],
                       source_intents: [recon_checks_intent(101), recon_checks_intent(202)],
                       next_entry_id: 2, money_before: recon_checks_snapshots, money_after: recon_checks_snapshots,
                       source: nil, checkpoint: nil, **options)
    source_tables = recon_checks_canonical(source_tables)
    checkpoint_tables = recon_checks_canonical(checkpoint_tables)
    projection ||= recon_checks_projection(checkpoint_tables["entries"])
    # A prebuilt checkpoint lets a test hand over rows Checkpoint.build would refuse,
    # or keep hold of the exact objects run receives.
    source ||= Timekeeping::Handoff::Checkpoint.build(tables: source_tables)
    checkpoint ||= Timekeeping::Handoff::Checkpoint.build(tables: checkpoint_tables)
    described_class.run(
      source:, checkpoint:,
      projection:, source_intents:, intents:, next_entry_id:, money_before:, money_after:, **options
    )
  end

  def expect_recon_checks_abort_in_a(result, check, reason:, field: :any)
    differences = result.companies.fetch(101).checks.fetch(check)
    expect(differences.map(&:reason)).to include(reason)
    expect(differences.map(&:field)).to include(field) unless field == :any
    expect(differences.map(&:company_id).uniq).to eq([101])
    expect(result.unassigned).to eq([])
    expect(result).to be_abort
    expect(result.companies.fetch(101)).to be_abort
    expect(result.companies.fetch(202)).not_to be_abort
    expect(result.companies.fetch(202).checks.values.flatten).to eq([])
  end

  # Collects the INSERT, UPDATE and DELETE statements issued while the block runs.
  def recon_checks_writes_during(&)
    writes = []
    watcher = lambda do |*, payload|
      sql = payload[:sql].to_s
      writes << sql if sql.match?(/\A\s*(INSERT|UPDATE|DELETE)\b/i)
    end
    ActiveSupport::Notifications.subscribed(watcher, "sql.active_record", &)
    writes
  end

  # The projection stores integer enums, so a missing conversion would flag every row.
  it "passes a clean two-company run with integer projection enums, every check present and empty, and no event" do
    projection = recon_checks_projection(recon_checks_tables["entries"])
    expect(projection.map { |row| [row["bill_status"], row["review_status"]] }.flatten).to all(be_an(Integer))

    result = recon_checks_run(projection:)
    expect(result).not_to be_abort
    expect(result.unassigned).to eq([])
    expect(result.to_h.fetch("companies").keys).to contain_exactly(101, 202)
    result.companies.each_value do |report|
      expect(report.checks.keys).to eq(described_class::CHECKS.keys)
      expect(report.checks.values).to all(eq([]))
    end

    assert_no_event_reported("Timekeeping::ReconciliationDifferenceFound") do
      assert_no_event_reported("Timekeeping::FinancialSnapshotChanged") do
        described_class.report(result)
      end
    end
  end

  it "reports a changed version and an extra entry under the company they belong to" do
    changed = recon_checks_run(checkpoint_tables: recon_checks_tables(entries: [recon_checks_entry(101, version: 2)]))
    expect_recon_checks_abort_in_a(changed, :entries, reason: :changed, field: "version")

    extra = recon_checks_tables(entries: [recon_checks_entry(101), recon_checks_entry(101, id: 9, locked: false)])
